parameters.jsCode:
const j = $input.first().json ?? {};

const sources = Array.isArray(j.sources) ? j.sources : [];

const sourceDocument = j.source_document
  ?? sources
    .map((s) => s.document_title || s.source_file)
    .filter(Boolean)
    .join(', ')
  ?? '';

const channelId = String(j.channel_id ?? j.slack_channel_id ?? '');
const threadTs = String(j.thread_ts ?? j.slack_thread_ts ?? '');
const safeThread = threadTs.replace(/[^0-9]/g, '');

const caseId = j.case_id
  ?? `ESC-${channelId || 'NOCHANNEL'}-${safeThread || Date.now()}`;

const incomingStatus = String(j.status ?? '').toLowerCase();
const status = incomingStatus === 'resolved'
  ? 'Resolved'
  : incomingStatus === 'in_review' || incomingStatus === 'in review'
    ? 'In Review'
    : 'Pending';

return [{
  json: {
    case_id: caseId,
    question: String(j.question ?? ''),
    slack_user_id: String(j.user_id ?? j.slack_user_id ?? ''),
    channel_id: channelId,
    thread_ts: threadTs,
    escalation_reason: String(j.reason ?? j.escalation_reason ?? 'Insufficient approved knowledge for a grounded answer.'),
    retrieved_context: String(j.retrieved_context ?? j.context ?? ''),
    source_document: String(sourceDocument || ''),
    status,
    human_answer: String(j.human_answer ?? ''),
    created_at: String(j.created_at ?? new Date().toISOString()),
    resolved_at: j.resolved_at ? String(j.resolved_at) : ''
  }
}];

const escalation = $('Normalize Escalation Record').first().json;
const airtable = $input.first().json ?? {};

return [{
  json: {
    success: true,
    case_id: escalation.case_id,
    airtable_record_id: airtable.id ?? '',
    status: escalation.status,
    question: escalation.question,
    channel_id: escalation.channel_id,
    thread_ts: escalation.thread_ts,
    message: `Escalation ${escalation.case_id} was logged for human review.`
  }
}];

